def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); st = list(feats.stratum); levs = sorted(set(st))
    Z = np.ones((n, 1))
    if len(levs) > 1:
        Z = np.column_stack([Z] + [np.array([s == l for s in st], float) for l in levs[1:]])
    def ll(A):
        A = np.column_stack([Z, A]) if A is not None and A.size else Z
        b = np.zeros(A.shape[1])
        for _ in range(30):
            m = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30))); w = m * (1 - m) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            s = np.linalg.solve(H, A.T @ (y - m)); b += s
            if np.abs(s).max() < 1e-7: break
        m = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    cols = lambda S: X[:, S] if S else None
    sel = []; base = ll(None); gates = [0.25 / p, 0.25 / p, 0.05 / p]
    while len(sel) < MAX_DRIVERS:
        best, bj = -1, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            g = 2 * (ll(cols(sel + [j])) - base)
            if g > best: best, bj = g, j
        if bj is None or stats.chi2.sf(best, 1) > gates[min(len(sel), 2)]: break
        cl = [k for k in range(p) if abs(R[bj, k]) >= 0.6 and k not in sel]
        if len(cl) > 1:
            lls = {k: ll(cols(sel + [k])) for k in cl}; top = max(lls.values())
            cand = [k for k in cl if lls[k] >= top - 2]
            def cost(k):
                return sum(max(0, ll(cols(sel + [k, o])) - lls[k]) for o in cl if o != k)
            bj = min(cand, key=cost)
        sel.append(bj); base = ll(cols(sel))
    changed = True
    while changed and len(sel) > 1:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (base - ll(cols(rest))), 1) > 0.25 / p:
                sel = rest; base = ll(cols(sel)); changed = True; break
    if not sel:
        best, bp = -1, None
        top = np.argsort([-abs(stats.pearsonr(X[:, j], y)[0]) for j in range(p)])[:15]
        for a in range(p):
            for b in top:
                if a == b or abs(R[a, b]) < 0.6: continue
                g = 2 * (ll(X[:, [a, b]]) - base)
                if g > best: best, bp = g, (a, b)
        if bp and stats.chi2.sf(best, 2) < 0.05 / (15 * p):
            sel = list(bp); base = ll(cols(sel))
    m0 = 1 / (1 + np.exp(-0.0)); r0 = y - y.mean()
    sc = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            v = X[:, a] * X[:, b]; v = v - v.mean()
            sc.append((abs(v @ r0) / (np.sqrt(v @ v) + 1e-9), a, b))
    sc.sort(reverse=True); prods = []; npair = p * (p + 1) / 2
    for _, a, b in sc[:20]:
        mains = sorted(set(sel) | {a, b}); l0 = ll(X[:, mains])
        v = (X[:, a] * X[:, b])[:, None]
        g = 2 * (ll(np.column_stack([X[:, mains], v])) - l0)
        if stats.chi2.sf(g, 1) < 0.005 / npair: prods.append((g, a, b))
    prods.sort(reverse=True); P = []; used = set()
    for g, a, b in prods:
        if len(P) < 2 and not ({a, b} & used): P.append((a, b)); used |= {a, b}
    drv = [ids[j] for j in sel]
    for a, b in P:
        for k in (a, b):
            if ids[k] not in drv: drv.append(ids[k])
    drv = tuple(drv[:MAX_DRIVERS])
    if not drv: return Design(drivers=(), columns=(), products=(), loadings={})
    colset = tuple(dict.fromkeys([ids[j] for j in sel] + [ids[k] for a, b in P for k in (a, b)]))
    return Design(drivers=drv, columns=colset, products=tuple((ids[a], ids[b]) for a, b in P), loadings={})

